#!/usr/bin/env python3
"""Render a fail-closed [tools]/[settings] projection of a mise TOML config."""
from __future__ import annotations

import argparse
import datetime as dt
import json
import os
import re
import sys
import tempfile
import tomllib
from pathlib import Path
from typing import Any

BARE_KEY = re.compile(r"^[A-Za-z0-9_-]+$")
# Deliberately project only the non-secret setting required by this workspace.
ALLOWED_SETTINGS = {"experimental": bool}


def fail(path: str, message: str) -> None:
    raise ValueError(f"{path}: {message}")


def key(value: str) -> str:
    return value if BARE_KEY.fullmatch(value) else json.dumps(value, ensure_ascii=False)


def transform(value: Any, path: str, source_home: str, remote_home: str, settings: bool) -> Any:
    if isinstance(value, str):
        if settings and value.startswith("/"):
            if value == source_home or value.startswith(source_home + "/"):
                value = remote_home + value[len(source_home):]
            else:
                fail(path, "absolute path is not under the source home")
        if settings and (value.startswith("/Users/") or "/Users/" in value):
            fail(path, "contains a macOS home path")
        return value
    if isinstance(value, list):
        return [transform(v, f"{path}[{i}]", source_home, remote_home, settings) for i, v in enumerate(value)]
    if isinstance(value, dict):
        if not all(isinstance(k, str) for k in value):
            fail(path, "has a non-string table key")
        return {k: transform(v, f"{path}.{k}", source_home, remote_home, settings) for k, v in value.items()}
    if isinstance(value, (bool, int, float, dt.date, dt.time, dt.datetime)) or value is None:
        return value
    fail(path, f"unsupported TOML type {type(value).__name__}")


def toml_value(value: Any, path: str) -> str:
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if value != value or value in (float("inf"), float("-inf")):
            fail(path, "non-finite float is unsupported")
        return repr(value)
    if isinstance(value, (dt.datetime, dt.date, dt.time)):
        return value.isoformat()
    if isinstance(value, list):
        return "[" + ", ".join(toml_value(v, f"{path}[{i}]") for i, v in enumerate(value)) + "]"
    if isinstance(value, dict):
        return "{ " + ", ".join(f"{key(k)} = {toml_value(value[k], f'{path}.{k}')}" for k in sorted(value)) + " }"
    fail(path, f"unsupported TOML type {type(value).__name__}")


def render_table(name: str, values: dict[str, Any]) -> str:
    lines = [f"[{name}]"]
    for name in sorted(values):
        lines.append(f"{key(name)} = {toml_value(values[name], name)}")
    return "\n".join(lines)


def render(source: Path, remote_home: str) -> str:
    try:
        with source.open("rb") as handle:
            config = tomllib.load(handle)
    except (OSError, tomllib.TOMLDecodeError) as exc:
        raise ValueError(f"source config is unreadable or invalid TOML: {exc}") from exc
    tools = config.get("tools")
    settings = config.get("settings", {})
    if not isinstance(tools, dict):
        fail("tools", "missing or not a table")
    if not isinstance(settings, dict):
        fail("settings", "not a table")
    source_home = str(Path.home())
    tools = transform(tools, "tools", source_home, remote_home, False)
    projected_settings: dict[str, bool] = {}
    for name, value in settings.items():
        if name not in ALLOWED_SETTINGS:
            fail(f"settings.{name}", "unsupported setting")
        expected_type = ALLOWED_SETTINGS[name]
        if type(value) is not expected_type:
            fail(f"settings.{name}", f"must be a {expected_type.__name__}")
        projected_settings[name] = value
    if "experimental" not in projected_settings:
        fail("settings.experimental", "required boolean setting is missing")
    return render_table("tools", tools) + "\n\n" + render_table("settings", projected_settings) + "\n"


def self_test() -> None:
    with tempfile.TemporaryDirectory() as temp:
        source = Path(temp) / "config.toml"
        source.write_text('[env]\nsecret = "synthetic-secret"\n[tools]\nnode = "24"\n"npm:x" = { version = "1", postinstall = ["x"] }\n[settings]\nexperimental = true\n')
        output = render(source, "/home/exedev")
        assert "synthetic-secret" not in output and "[env]" not in output
        assert "experimental = true" in output


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", default=os.path.expanduser("~/.config/mise/config.toml"))
    parser.add_argument("--remote-home", required=False)
    parser.add_argument("--output")
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()
    if args.self_test:
        self_test()
        return 0
    if not args.remote_home or not args.remote_home.startswith("/"):
        parser.error("--remote-home must be an absolute remote home directory")
    try:
        output = render(Path(args.source).expanduser(), args.remote_home)
    except ValueError as exc:
        print(f"sanitize-mise-config: {exc}", file=sys.stderr)
        return 1
    if args.output:
        destination = Path(args.output)
        destination.write_text(output)
        destination.chmod(0o600)
    else:
        sys.stdout.write(output)
    return 0


