#!/usr/bin/env bash
# Static VM-local helper. Prompt content arrives only on stdin for `start`.
set -Eeuo pipefail
IFS=$'\n\t'

mode=${1:?mode required}
job_id=${2:?job id required}
[[ $job_id =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$ ]] || { echo 'invalid job id' >&2; exit 2; }
repo_dir=${EXE_VM_REPO_DIR:-"$HOME/src/sof-pi"}
root="$HOME/.local/share/sof-pi-workspace"
helper="$root/exe-workspace-job.sh"
job_root="$root/jobs/$job_id"
worktree="$root/worktrees/$job_id"
session="sof-pi-$job_id"
status="$job_root/status.json"
log="$job_root/job.log"
base_sha=
started_at=

valid_primary() {
  [ -d "$repo_dir/.git" ] &&
    [ "$(git -C "$repo_dir" remote get-url origin)" = 'https://sof-pi.int.exe.xyz/BbrSofiane/sof-pi.git' ] &&
    [ "$(git -C "$repo_dir" symbolic-ref --quiet --short HEAD)" = main ] &&
    git -C "$repo_dir" diff --quiet &&
    git -C "$repo_dir" diff --cached --quiet &&
    [ -z "$(git -C "$repo_dir" status --porcelain --untracked-files=all)" ]
}

json_string() {
  # Job IDs, paths, and commit IDs are all controlled/validated, but JSON escaping remains explicit.
  python3 -c 'import json, sys; print(json.dumps(sys.argv[1]))' "$1"
}

write_status() {
  local state=$1 code=${2:-null} temporary now
  now=$(date -u +%Y-%m-%dT%H:%M:%SZ)
  temporary=$(mktemp "$job_root/status.XXXXXX")
  {
    printf '{"id":%s,"state":%s,"branch":%s,"worktree":%s,"session":%s,"base":%s,"started_at":%s,"ended_at":%s,"exit_code":%s}\n' \
      "$(json_string "$job_id")" "$(json_string "$state")" "$(json_string "pi/$job_id")" \
      "$(json_string "$worktree")" "$(json_string "$session")" "$(json_string "$base_sha")" \
      "$(json_string "$started_at")" "$(json_string "$now")" "$code"
  } >"$temporary"
  chmod 0600 "$temporary"
  mv -f "$temporary" "$status"
}

run_job() {
  local code=0
  base_sha=$(git -C "$worktree" rev-parse HEAD 2>/dev/null || true)
  started_at=$(date -u +%Y-%m-%dT%H:%M:%SZ)
  trap 'code=$?; write_status finished "$code"; exit "$code"' EXIT
  cd "$worktree"
  pi --no-session -p <"$job_root/prompt.md" >>"$log" 2>&1
}

rollback_start() {
  # Preconditions establish that these job-specific resources did not exist before start.
  tmux has-session -t "$session" 2>/dev/null && tmux kill-session -t "$session" || true
  [ ! -e "$worktree" ] || git -C "$repo_dir" worktree remove --force "$worktree" || true
  git -C "$repo_dir" show-ref --verify --quiet "refs/heads/pi/$job_id" && git -C "$repo_dir" branch -D "pi/$job_id" || true
  [ ! -e "$job_root" ] || rm -rf -- "$job_root"
}

start() {
  valid_primary || { echo 'primary checkout unavailable, unexpected, or dirty' >&2; return 1; }
  # Check all external launch prerequisites before creating any job-specific state.
  command -v git >/dev/null && command -v python3 >/dev/null && command -v tmux >/dev/null && command -v flock >/dev/null || { echo 'job prerequisites are unavailable' >&2; return 1; }
  [ -x "$helper" ] || { echo 'installed job helper is unavailable' >&2; return 1; }
  install -d -m 0700 "$root" "$root/jobs" "$root/worktrees"
  exec 9>"$root/git.lock"
  flock -n 9 || { echo 'job setup lock is busy' >&2; return 1; }
  [ ! -e "$job_root" ] && [ ! -e "$worktree" ] || { echo 'job id already exists' >&2; return 1; }
  ! tmux has-session -t "$session" 2>/dev/null || { echo 'job tmux session already exists' >&2; return 1; }
  ! git -C "$repo_dir" show-ref --verify --quiet "refs/heads/pi/$job_id" || { echo 'job branch already exists' >&2; return 1; }
  install -d -m 0700 "$job_root" || return 1
  umask 077
  if ! cat >"$job_root/prompt.md" || ! chmod 0600 "$job_root/prompt.md" || ! : >"$log" || ! chmod 0600 "$log"; then
    rollback_start
    return 1
  fi
  if ! base_sha=$(git -C "$repo_dir" rev-parse HEAD) || ! started_at=$(date -u +%Y-%m-%dT%H:%M:%SZ) || ! git -C "$repo_dir" fetch --quiet origin main || ! git -C "$repo_dir" worktree add -b "pi/$job_id" "$worktree" "$base_sha" || ! write_status starting null || ! tmux new-session -d -s "$session" -c "$worktree" "$helper" run "$job_id" || ! write_status running null; then
    rollback_start
    return 1
  fi
  flock -u 9
}

case "$mode" in
  start) start ;;
  run) run_job ;;
  status)
    [ -f "$status" ] || { echo 'job status unavailable' >&2; exit 1; }
    cat "$status"
    tmux has-session -t "$session" 2>/dev/null && printf 'tmux=present\n' || printf 'tmux=absent\n'
    ;;
  logs)
    [ -f "$log" ] || { echo 'job log unavailable' >&2; exit 1; }
    tail -n 200 "$log"
    ;;
  attach) exec tmux attach-session -t "$session" ;;
  stop)
    tmux has-session -t "$session" 2>/dev/null || { echo 'job session unavailable' >&2; exit 1; }
    tmux send-keys -t "$session" C-c
    for _ in 1 2 3 4 5; do
      sleep 1
      tmux has-session -t "$session" 2>/dev/null || { write_status stopped 130; exit 0; }
    done
    write_status stop-timeout null
    tmux kill-session -t "$session"
    ;;
  *) echo 'unknown job mode' >&2; exit 2 ;;
esac

#!/usr/bin/env bash
# Local control plane for the one private exe.dev workspace VM.
set -Eeuo pipefail
IFS=$'\n\t'

readonly ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
readonly VM_NAME=${EXE_VM_NAME:-sof-pi-workspace}
readonly VM_HOST=${EXE_VM_HOST:-sof-pi-workspace.exe.xyz}
readonly VM_TAG=sof-pi
readonly REPO_URL=https://sof-pi.int.exe.xyz/BbrSofiane/sof-pi.git
readonly REPO_DIR=${EXE_VM_REPO_DIR:-"$HOME/src/sof-pi"}
readonly SOURCE_CONFIG=${MISE_SOURCE_CONFIG:-"$HOME/.config/mise/config.toml"}
readonly CONNECT_TIMEOUT=${EXE_VM_CONNECT_TIMEOUT:-10}
readonly READY_RETRIES=${EXE_VM_READY_RETRIES:-12}
readonly MARKER="__SOF_PI_WORKSPACE_$(od -An -N12 -tx1 /dev/urandom | tr -d ' \n')__"
SSH_OPTIONS=(-o BatchMode=yes -o "ConnectTimeout=$CONNECT_TIMEOUT" -o StrictHostKeyChecking=accept-new)
cleanup_files=()

cleanup() {
  local file
  if [ "${#cleanup_files[@]}" -gt 0 ]; then
    for file in "${cleanup_files[@]}"; do
      [ -n "$file" ] && rm -f -- "$file"
    done
  fi
  return 0
}
trap cleanup EXIT

fail() { printf 'exe-workspace: %s\n' "$*" >&2; exit 1; }
require() { command -v "$1" >/dev/null 2>&1 || fail "required command unavailable: $1"; }
valid_name() { [[ $1 =~ ^[A-Za-z0-9][A-Za-z0-9-]{0,62}$ ]]; }
valid_job_id() { [[ $1 =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$ ]]; }

validate_config() {
  valid_name "$VM_NAME" || fail 'invalid EXE_VM_NAME'
  [[ $VM_HOST == "$VM_NAME.exe.xyz" ]] || fail 'EXE_VM_HOST must match EXE_VM_NAME.exe.xyz'
  [[ $CONNECT_TIMEOUT =~ ^[1-9][0-9]?$ && $READY_RETRIES =~ ^[1-9][0-9]?$ ]] || fail 'invalid bounded timeout/retry value'
  [[ $REPO_DIR == "$HOME"/* && $REPO_DIR != *$'\n'* && $REPO_DIR != *' '* ]] || fail 'EXE_VM_REPO_DIR must be an absolute path below local HOME without whitespace'
}

check_local() {
  validate_config
  require ssh
  require python3
  require mise
  require git
  require jq
}
lobby() { ssh "${SSH_OPTIONS[@]}" exe.dev "$@"; }
direct() { ssh "${SSH_OPTIONS[@]}" "$VM_HOST" "$@"; }

vm_state_from_json() {
  local json=$1 matches
  matches=$(jq -er --arg name "$VM_NAME" '[.vms | if type == "array" then .[] else error("vms must be an array") end | select(.vm_name == $name)] | length' <<<"$json") || { printf 'exe-workspace: malformed lifecycle JSON\n' >&2; return 1; }
  case "$matches" in
    0) printf 'absent\n' ;;
    1)
      jq -e --arg name "$VM_NAME" --arg host "$VM_HOST" '
        .vms[] | select(.vm_name == $name)
        | select(.ssh_dest == $host)
        | select(.status == "running" or .status == "creating" or .status == "stopped")
      ' <<<"$json" >/dev/null || { printf 'exe-workspace: existing VM host or state is unexpected\n' >&2; return 1; }
      printf 'existing\n'
      ;;
    *) printf 'exe-workspace: more than one exact VM name exists\n' >&2; return 1 ;;
  esac
}

private_vm_verified() {
  local lifecycle=$1
  jq -e --arg name "$VM_NAME" '
    .vms[] | select(.vm_name == $name)
    | select(.sharing | type == "object")
    | select(.sharing.public_proxy | type == "boolean" and . == false)
  ' <<<"$lifecycle" >/dev/null || { printf 'exe-workspace: existing VM privacy state is missing, malformed, or public\n' >&2; return 1; }
}

tag_verified() {
  local tag_json=$1
  jq -e --arg tag "$VM_TAG" --arg name "$VM_NAME" '
    .groups | if type == "array" then .[] else error("groups must be an array") end
    | select(.label == $tag or .label == ("#" + $tag))
    | .vm_names | if type == "array" then index($name) != null else error("vm_names must be an array") end
  ' <<<"$tag_json" >/dev/null || { printf 'exe-workspace: existing VM does not have the required sof-pi tag\n' >&2; return 1; }
}

integration_verified() {
  local integrations=$1
  jq -e --arg tag "tag:$VM_TAG" '
    if type != "array" then error("integrations must be an array") else . end
    | any(.[]; .name == "sof-pi" and .type == "github" and (.attachments | type == "array" and index($tag) != null))
  ' <<<"$integrations" >/dev/null
}

inspect_vm() {
  local lifecycle tag_json result
  lifecycle=$(lobby ls --json) || fail 'cannot inspect VM lifecycle state'
  result=$(vm_state_from_json "$lifecycle") || return 1
  if [ "$result" = existing ]; then
    private_vm_verified "$lifecycle" || return 1
    tag_json=$(lobby ls --group=tag --json) || fail 'cannot inspect VM tag membership'
    tag_verified "$tag_json" || return 1
  fi
  printf '%s\n' "$result"
}

state() { check_local; inspect_vm; }
ready() {
  local attempt
  for ((attempt = 1; attempt <= READY_RETRIES; attempt++)); do
    direct true >/dev/null 2>&1 && return 0
    sleep "$attempt"
  done
  fail "VM did not become reachable after $READY_RETRIES attempts"
}
require_existing() {
  [ "$(state)" = existing ] || fail 'expected VM is absent'
  ready
}

status() {
  local lifecycle current integrations integration_status
  check_local
  lifecycle=$(lobby ls --json) || fail 'cannot inspect VM lifecycle state'
  current=$(vm_state_from_json "$lifecycle")
  if [ "$current" = absent ]; then
    printf 'name=%s host=%s state=absent tag=%s github-integration=not-applicable\n' "$VM_NAME" "$VM_HOST" "$VM_TAG"
    return 0
  fi
  tag_verified "$(lobby ls --group=tag --json)"
  integrations=$(lobby integrations list --json) || fail 'cannot inspect GitHub integration prerequisite'
  if integration_verified "$integrations"; then integration_status=verified; else integration_status=missing-or-unconfirmed; fi
  jq -r --arg name "$VM_NAME" '.vms[] | select(.vm_name == $name) | "name=" + .vm_name + " host=" + .ssh_dest + " status=" + .status + " region=" + (.region // "unknown") + " private=" + (((.sharing.public_proxy // false) | not) | tostring)' <<<"$lifecycle"
  printf 'tag=verified github-integration=%s\n' "$integration_status"
}

create() {
  check_local
  lobby whoami >/dev/null || fail 'exe.dev authentication failed'
  local current
  current=$(inspect_vm) || return 1
  case "$current" in
    existing) printf 'VM already exists and identity is valid: %s\n' "$VM_NAME"; ready ;;
    absent)
      cat "$ROOT/scripts/exe-workspace-setup.sh" | lobby new "--name=$VM_NAME" "--tag=$VM_TAG" --setup-script /dev/stdin --json
      ready
      ;;
  esac
}

remote_bootstrap() { direct 'bash -s --' "$@" <"$ROOT/scripts/exe-workspace-bootstrap.sh"; }

sync() {
  check_local
  require_existing
